/**
 * Builds a self-contained, upload-ready copy of the app.
 *
 *   npm run bundle:deploy
 *
 * Vercel accepts a plain folder upload, which skips the GitHub dance entirely.
 * This produces that folder: `invoice-deploy/` at the repo root, containing
 * every file the build and the server need, and nothing else.
 *
 * Deliberately excluded, and why:
 *   node_modules  454 MB — Vercel runs `npm install` itself
 *   .git          history and remotes, not build input
 *   .next         build output; the target regenerates it
 *   .env.local    real secrets. Shipping it would defeat the whole exercise.
 *   tmp/          probe output
 *   tsbuildinfo   local compiler cache
 *   readme.txt    the original brief, not needed to run anything
 *
 * The folder is git-ignored and excluded from tsconfig/eslint, so a copy of the
 * source living inside the source cannot confuse the parent build.
 */
import { cp, mkdir, rm, writeFile, readdir, stat } from "node:fs/promises";
import { join, relative } from "node:path";

const ROOT = process.cwd();
const OUT = join(ROOT, "invoice-deploy");

/** Directories copied wholesale. */
const DIRS = ["app", "components", "lib", "types", "supabase", "scripts"];

/** Single files copied as-is. */
const FILES = [
  "package.json",
  "package-lock.json",
  "next.config.ts",
  "tsconfig.json",
  "tailwind.config.ts",
  "postcss.config.mjs",
  "eslint.config.mjs",
  "next-env.d.ts",
  "middleware.ts",
  ".env.example",
  ".gitignore",
  "README.md",
];

const NEVER_SHIP = [
  "node_modules",
  ".git",
  ".next",
  ".vercel",
  ".env",
  ".env.local",
  ".env.production.local",
  "invoice-deploy",
  "tmp",
  "tsconfig.tsbuildinfo",
  "readme.txt",
];

async function count(dir) {
  let files = 0;
  let bytes = 0;
  const walk = async (d) => {
    for (const entry of await readdir(d, { withFileTypes: true })) {
      if (entry.name === "node_modules" || entry.name === ".next") continue;
      const full = join(d, entry.name);
      if (entry.isDirectory()) await walk(full);
      else {
        files += 1;
        bytes += (await stat(full)).size;
      }
    }
  };
  await walk(dir);
  return { files, bytes };
}

await rm(OUT, { recursive: true, force: true });
await mkdir(OUT, { recursive: true });

for (const dir of DIRS) {
  await cp(join(ROOT, dir), join(OUT, dir), {
    recursive: true,
    filter: (src) => !NEVER_SHIP.some((skip) => src.endsWith(`\\${skip}`) || src.endsWith(`/${skip}`)),
  });
}

for (const file of FILES) {
  await cp(join(ROOT, file), join(OUT, file));
}

const readme = `# Invoice Generator — Vercel upload bundle

Generated by \`npm run bundle:deploy\`. Everything the build and the running app
need is in here. **No secrets are.** Add yours in Vercel.

## Deploy in four steps

1. **Rotate your Supabase secret key first.** The key that was pasted into chat
   must be reset: Supabase -> Project Settings -> API Keys -> Reset.

2. **Upload this folder.** <https://vercel.com/new> -> *Deploy* -> drag this
   whole \`invoice-deploy\` folder onto the drop zone. Framework is detected as
   Next.js automatically.

3. **Add three environment variables.** Project -> Settings -> Environment
   Variables. Tick Production, Preview and Development for each:

   | Name | Value |
   | --- | --- |
   | \`NEXT_PUBLIC_SUPABASE_URL\` | \`https://ayuzkbjywyzryotwnbpk.supabase.co\` |
   | \`NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY\` | your publishable \`sb_publishable_…\` key |
   | \`SUPABASE_SECRET_KEY\` | your **new** \`sb_secret_…\` key |

   \`NEXT_PUBLIC_APP_URL\` is optional (falls back to \`VERCEL_URL\`).
   \`PAYMENT_MODE\` defaults to \`disabled\`, \`EMAIL_PROVIDER\` to \`console\`.

4. **Redeploy, then fix login.** Deployments -> ... -> Redeploy, because
   \`NEXT_PUBLIC_*\` values are baked in at build time. Then Supabase ->
   Authentication -> URL Configuration:
   - Site URL: \`https://<your-domain>\`
   - Redirect URLs: \`https://<your-domain>/**\` and \`https://*.vercel.app/**\`

## Verify

\`\`\`
curl https://<your-domain>/api/health
\`\`\`

Expect \`"ok":true\` and \`"schema":{"ok":true}\`. Then sign in, create an invoice,
download the PDF, and open the share link in a private window.

## Note on \`scripts/\`

Kept so \`npm run check:secrets\` and \`npm run pdf:check\` still work. Delete the
folder before uploading if you want the bundle as small as possible — Vercel does
not need it.
`;

await writeFile(join(OUT, "DEPLOY-THIS-FOLDER.md"), readme, "utf8");

const { files, bytes } = await count(OUT);
console.log(`\nDeploy bundle written to ${relative(ROOT, OUT)}\\`);
console.log(`  ${files} files, ${(bytes / 1024).toFixed(0)} KB`);
console.log(`  excluded: ${NEVER_SHIP.join(", ")}\n`);